	/** 
	 * jumpstart the process by instantiating2 Channel
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		channelId = ChannelService.getChannelInstance()
		.createChannel( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ChannelService.getChannelInstance()
				.createChannel( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.channelSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Channel : " + successValue.getChannelId());
							  if (successValue.getChannelId().equals(channelId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfChannelList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Channel test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on channel consumed")
					);
			subscriber.channelSubscribe( channelId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Channel : " + successValue.getChannelId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfChannelList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on channel for channelId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Channel. 
	 */
	protected Channel read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Channel" );

		Channel entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Channel with primary key" );
		msg.append( channelId );
		
		ChannelFetchOneSummary fetchOneSummary = new ChannelFetchOneSummary( channelId );

		try {
			entity = ChannelService.getChannelInstance().getChannel( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Channel " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Channel.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Channel." );

		StringBuilder msg = new StringBuilder( "Failed to update a Channel : " );        
		Channel entity = read();
		UpdateChannelCommand command = generateUpdateCommand();
		command.setChannelId(entity.getChannelId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Channel." );

			// for use later on...
			channelId = entity.getChannelId();

			ChannelService proxy = ChannelService.getChannelInstance();  

			proxy.updateChannel( command ).get();

			LOGGER.info( "-- Successfully saved Channel - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + channelId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Channel.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Channel." );

		Channel entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Channel with id " + channelId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Channel with id " + channelId );

			throw e;
		}

		try{
			ChannelService.getChannelInstance().delete( new DeleteChannelCommand( entity.getChannelId() ) ).get();
			LOGGER.info( "-- Successfully deleted Channel with id " + channelId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Channel with id " + channelId );

			throw e;
		}
	}

	/**
	 * get all Channels.
	 */
	protected List<Channel> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Channels:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Channel : " );        
		List<Channel> collection  = new ArrayList<>();

		try {
			// call the static get method on the ChannelService
			collection = ChannelService.getChannelInstance().getAllChannel();
			assertNotNull( collection, "An Empty collection of Channel was incorrectly returned.");
			
			// Now print out the values
			Channel entity = null;            
			Iterator<Channel> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getChannelId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

